export {galleryCapacity,GalleryCapacityError} from './linearGalleryVariablePopulation';
import {layeredGallery} from './linearGalleryLayers';
import type {AmphitheaterRequest,AmphitheaterSource} from './amphitheaterInteractiveTypes';
export type GallerySettings={footprint?:import('./linearGalleryPerimeter').FootprintControls;architectureVersion?:'legacy-v2'|'receiver-v3';arrangementMode?:'source-gaps'|'defined-levels';nominalSpacing?:12|13|14|15;version?:'polygonal-v2';separations?:[5|10|15,5|10|15,5|10|15];path:[number,number][];width:number;levels:number;spacing:number;seed:number};
export function defaultGallery(f:AmphitheaterRequest['field'],size:number,seed:number):GallerySettings{return {version:'polygonal-v2',separations:[5,10,15],path:[[-f.width*.2,-f.depth*.1],[0,f.depth*.1],[f.width*.2,-f.depth*.1]],width:size*.6,levels:5,spacing:Math.min(15,f.height*.25),seed};}
export function validateGallery(s:GallerySettings){if(s?.arrangementMode!==undefined&&!['source-gaps','defined-levels'].includes(s.arrangementMode))throw Error('Unknown gallery arrangement mode.');if(s?.arrangementMode==='defined-levels'&&![12,13,14,15].includes(s.nominalSpacing??13))throw Error('Nominal gallery spacing must be 12, 13, 14 or 15 ft.');if(!s||!Array.isArray(s.path)||s.path.length<2||s.path.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)))||!Number.isFinite(s.width)||s.width<=0||!Number.isSafeInteger(s.levels)||s.levels<1||!Number.isFinite(s.spacing)||s.spacing<=0||!Number.isSafeInteger(s.seed))throw Error('Invalid ordered gallery path or levels.');if(s.path.slice(1).some((p,i)=>Math.hypot(p[0]-s.path[i][0],p[1]-s.path[i][1])<1e-6))throw Error('Zero-length gallery segment.');}
export function populateGallery(count:number,f:AmphitheaterRequest['field'],size:number,s:GallerySettings){
validateGallery(s);if(s.version==='polygonal-v2')return layeredGallery(count,f,size,s);if(!Number.isSafeInteger(count)||count<s.levels*3||!Number.isFinite(size)||size<=0)throw Error('Supply at least three letters per level and a positive size.');
let state=s.seed>>>0;const random=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};
const lengths=s.path.slice(1).map((p,i)=>Math.hypot(p[0]-s.path[i][0],p[1]-s.path[i][1])),total=lengths.reduce((a,b)=>a+b,0),source:AmphitheaterSource[]=[],stations:{segment:number;variation:number;stagger:number;role:string}[]=[];
for(let i=0;i<count;i++){const level=i%s.levels,rank=Math.floor(i/s.levels),n=Math.ceil((count-level)/s.levels);let d=total*(rank+.5)/n,j=0;while(j<lengths.length-1&&d>lengths[j])d-=lengths[j++];const a=s.path[j],b=s.path[j+1],t=d/lengths[j],dx=(b[0]-a[0])/lengths[j],dy=(b[1]-a[1])/lengths[j],letter=(['L','U','V'] as const)[rank%3],variation=(random()*2-1)*15,stagger=s.width*(.15+.2*random())*(rank%2?1:-1);
const p:AmphitheaterSource={letter,x:a[0]+(b[0]-a[0])*t-dy*stagger,y:a[1]+(b[1]-a[1])*t+dx*stagger,z:-f.height/2+size*.85+level*s.spacing,rx:letter==='L'?0:90,ry:0,rz:Math.atan2(dy,dx)*180/Math.PI+variation,rotationOrder:'ZYX',scale:size/.92,scaleX:1,scaleY:1,scaleZ:1,levelIndex:level,architecturalRole:letter==='L'?'terrace':letter==='U'?'interior':'perimeter'};
const radius=size*.8;if(Math.abs(p.x)+radius>f.width/2||Math.abs(p.y)+radius>f.depth/2||Math.abs(p.z)+radius>f.height/2)throw Error('Gallery source outside field; adjust path, levels or size.');
source.push(p);stations.push({segment:j,variation,stagger,role:letter==='L'?'circulation edge':letter==='U'?'occupation pocket':'angular transition'});}
return {source,stations,settings:s};
}
export function galleryArrangement(r:AmphitheaterRequest){if(r.envelopeVersion!=='linear-edge-gallery'||r.generator!=='source-preserving'||!r.linearGallery)throw Error('Gallery needs source-preserving Rule 5A settings.');validateGallery(r.linearGallery);if(!Array.isArray(r.source)||!r.source.length)throw Error('Gallery needs selected source letters.');if(typeof r.population==='number'&&r.population!==r.source.length)throw Error('Gallery quantity '+r.population+' does not match '+r.source.length+' selected letters. Use New Design to create the requested quantity; regeneration preserves the edited population and poses.');return {stage:'rule-5a',source:r.source,path:r.linearGallery.path,architecturePending:true};}
